package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoMotionReviewTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun motionActivity():HonorableVideoEditorActivity=activity().also{a->val p=get(a,"project")as VideoEditProject;val m=VideoMotion(true,1.123f,1.678f,-.123f,.234f,.345f,-.456f,0,5000,MotionEase.SMOOTH);p.restore(p.segments.map{it.copy(startMs=1000,endMs=4000,speed=2f,title="Motion",motion=m)},soundtrack=p.soundtrack)}
 private fun editor(a:HonorableVideoEditorActivity):AlertDialog=dialog().also{set(a,"inspectorReviewDialog",it);set(a,"captionReviewDialogs",linkedSetOf(it))}
 private fun commit(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoCaptionReviewState,motion:VideoMotion):Boolean{val p=get(a,"project")as VideoEditProject;return call(a,"commitInspectorReview",d,r,p,0,p.segments[0],{p.setMotion(0,motion)})as Boolean}
 @Test fun editedMotionOnlyChangesMotionWithOneUndoAndOriginalMetadata(){val a=motionActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val clip=old[0];val next=clip.motion.forEditing(clip.startMs,clip.endMs).copy(endZoom=2f,ease=MotionEase.LINEAR);val r=capture(a);val d=editor(a);assertTrue(commit(a,d,r,next));assertEquals(clip.copy(motion=next),p.segments[0]);assertSame(music,p.soundtrack);assertEquals(1000L,p.segments[0].motion.anchorStartMs);assertEquals(4000L,p.segments[0].motion.anchorEndMs);assertNull(get(a,"inspectorReviewDialog"));assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertEquals(next,p.segments[0].motion)}
 @Test fun untrackedDismissedOrReplacedMotionDialogCannotApply(){for(flag in listOf("untracked","dismissed","replaced")){val a=motionActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val r=capture(a);val d=editor(a);when(flag){"untracked"->set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());"dismissed"->showing(d,false);else->set(a,"inspectorReviewDialog",dialog())};assertFalse(flag,commit(a,d,r,VideoMotion()));assertSame(old,p.segments);assertFalse(p.canUndo)}}
 @Test fun staleForegroundGenerationSourceRangeSessionRecoveryAndMusicReject(){for(flag in listOf("pause","generation","source","duration","range","mode","recovery","busy","analysis","music")){val a=motionActivity();val p=get(a,"project")as VideoEditProject;val r=capture(a);val d=editor(a);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",r.generation+1);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"range"->set(a,"selectedClip",1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));"busy"->set(a,"saving",true);"analysis"->set(a,"analyzing",true);else->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f))};val before=p.segments;assertFalse(flag,commit(a,d,r,VideoMotion()));assertSame(before,p.segments);assertNull(get(a,"inspectorReviewDialog"))}}
 @Test fun oldInspectorCannotConsumeNewMotionOwnerOrReviveAfterUndo(){val a=motionActivity();val p=get(a,"project")as VideoEditProject;val old=editor(a);val current=editor(a);val r=capture(a);assertFalse(commit(a,old,r,VideoMotion()));assertSame(current,get(a,"inspectorReviewDialog"));assertTrue(commit(a,current,r,VideoMotion()));assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",r));assertFalse(commit(a,current,r,VideoMotion()));assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun projectValidationFailureKeepsOwnerForCorrectedMotion(){val a=motionActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val r=capture(a);val d=editor(a);val bad=old[0].motion.copy(anchorEndMs=6000);try{commit(a,d,r,bad);fail("Accepted motion past source")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException)};assertSame(old,p.segments);assertFalse(p.canUndo);assertSame(d,get(a,"inspectorReviewDialog"));val valid=old[0].motion.copy(endZoom=2f);assertTrue(commit(a,d,r,valid));assertNull(get(a,"inspectorReviewDialog"));assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo)}
 @Test fun legacyShowAndOwnedFactorySignaturesRemainAvailable(){val methods=VideoMotionControls::class.java.declaredMethods;assertTrue(methods.any{it.name=="show"&&it.parameterCount==3&&it.returnType==java.lang.Void.TYPE});assertTrue(methods.any{it.name=="create"&&it.parameterCount==4&&it.returnType==AlertDialog::class.java})}
 @Test fun customSourceAnchorsAndPrecisionSurviveEditingBaselineAndExistingCodec(){val a=motionActivity();val p=get(a,"project")as VideoEditProject;val clip=p.segments[0];val original=clip.motion;val baseline=original.forEditing(clip.startMs,clip.endMs);assertEquals(1000L,baseline.anchorStartMs);assertEquals(4000L,baseline.anchorEndMs);assertEquals(original.atSource(1000.0).zoom,baseline.startZoom);assertEquals(original.atSource(4000.0).zoom,baseline.endZoom);val draft=VideoDraft(5000,p.segments,0,clip.startMs,clip.startMs,clip.endMs,soundtrack=p.soundtrack);val restored=requireNotNull(VideoDraftCodec.decode(VideoDraftCodec.encode(draft),5000));assertEquals(draft,restored);assertEquals(0L,restored.segments[0].motion.anchorStartMs);assertEquals(5000L,restored.segments[0].motion.anchorEndMs);assertEquals(1.123f,restored.segments[0].motion.startZoom);assertEquals(-.456f,restored.segments[0].motion.endY);assertFalse(p.canUndo)}
 @Test fun pausedAnalysingOrRecoveringMotionEntryReturnsBeforeWidgets(){for(flag in listOf("pause","analysis","recovery")){val a=motionActivity();when(flag){"pause"->set(a,"workspaceActive",false);"analysis"->set(a,"analyzing",true);else->set(a,"recoveryBytes",byteArrayOf(1))};call(a,"editMotion");assertNull(get(a,"inspectorReviewDialog"));assertNull(get(a,"captionReviewDialogs"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
}
